def check_solution(a, b, c):
    # Check if (a+b+c)(ab+bc+ca+1) == 12abc
    s = a + b + c
    q = a*b + b*c + c*a
    p = a*b*c

    LHS = s * (q + 1)
    RHS = 12 * p

    return LHS == RHS

solutions = []
# Search space: 1 <= a < b < c <= 10
for a in range(1, 11):
    for b in range(a + 1, 11):
        for c in range(b + 1, 11):
            if check_solution(a, b, c):
                solutions.append((a, b, c))

print("Solutions found in the range 1 <= a < b < c <= 10:")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found.")
